// Navbar behaviour (mobile menu, dropdowns), language-switch hash keeping, scroll reveal.
// The navbar and footer markup itself is generated by build.py.
(function () {
  const nav = document.getElementById('site-nav');
  if (nav) {
    const toggle = nav.querySelector('.nav-toggle');
    const list = nav.querySelector('.nav-links');
    toggle.addEventListener('click', () => {
      const open = list.classList.toggle('open');
      toggle.setAttribute('aria-expanded', open);
    });

    // Dropdowns: hover on desktop (CSS), tap the ▾ button on touch / mobile.
    nav.querySelectorAll('.drop-btn').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const li = btn.parentElement;
        const open = !li.classList.contains('open');
        nav.querySelectorAll('.has-drop.open').forEach((x) => x !== li && x.classList.remove('open'));
        li.classList.toggle('open', open);
        btn.setAttribute('aria-expanded', open);
      });
    });
    document.addEventListener('click', (e) => {
      if (!nav.contains(e.target)) nav.querySelectorAll('.has-drop.open').forEach((x) => x.classList.remove('open'));
    });
    list.addEventListener('click', (e) => {
      if (e.target.tagName === 'A') {
        list.classList.remove('open');
        nav.querySelectorAll('.has-drop.open').forEach((x) => x.classList.remove('open'));
      }
    });

    // Keep the current section when switching language.
    nav.querySelectorAll('.lang-switch a').forEach((a) => {
      a.addEventListener('click', () => {
        if (location.hash) a.href = a.getAttribute('href').split('#')[0] + location.hash;
      });
    });
  }

  // Scroll reveal
  const els = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver((entries) => {
      entries.forEach((en) => { if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); } });
    }, { threshold: 0.08 });
    els.forEach((el) => io.observe(el));
  } else {
    els.forEach((el) => el.classList.add('in'));
  }
})();
